function clientIp(req: NextRequest): string | undefined {
  return (
    req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
    req.headers.get("x-real-ip") ||
    undefined
  );
}

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = req.nextUrl;
    const patients = await searchPatients({
      q: searchParams.get("q") ?? undefined,
      patientId: searchParams.get("patientId") ?? undefined,
      name: searchParams.get("name") ?? undefined,
      mobile: searchParams.get("mobile") ?? undefined,
      dob: searchParams.get("dob") ?? undefined,
    });
    return NextResponse.json({ patients });
  } catch (err) {
    console.error("GET /api/patients", err);
    return NextResponse.json(
      { error: "Failed to search patients" },
      { status: 500 },
    );
  }
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const parsed = createPatientSchema.parse(body);
    const patient = await createPatient(parsed, { ipAddress: clientIp(req) });
    return NextResponse.json({ patient }, { status: 201 });
  } catch (err) {
    if (err instanceof ZodError) {
      return NextResponse.json(
        { error: "Validation failed", details: err.flatten() },
        { status: 400 },
      );
    }
    console.error("POST /api/patients", err);
    return NextResponse.json(
      { error: "Failed to create patient" },
      { status: 500 },
    );
  }
}

import { z } from "zod";
import {
  assertPlausibleMeasurements,
  measurementBounds,
} from "@/lib/validations/patient";

const todayStart = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
};

const visitDateSchema = z
  .string()
  .or(z.date())
  .transform((v) => (v instanceof Date ? v : new Date(v)))
  .refine((d) => !Number.isNaN(d.getTime()), { message: "Invalid visit date" })
  .refine((d) => d <= todayStart(), {
    message: "Visit date cannot be in the future",
  });

const optionalDate = z
  .string()
  .or(z.date())
  .optional()
  .nullable()
  .transform((v) => {
    if (v == null || v === "") return null;
    return v instanceof Date ? v : new Date(v);
  })
  .refine((d) => d == null || !Number.isNaN(d.getTime()), {
    message: "Invalid date",
  });

export const addVisitSchema = z
  .object({
    visitDate: visitDateSchema,
    weightKg: measurementBounds.weightKg,
    heightCm: measurementBounds.heightCm,
    headCircumferenceCm: measurementBounds.headCircumferenceCm,
    notes: z.string().trim().max(2000).optional().nullable(),
    doctorAdvice: z.string().trim().max(2000).optional().nullable(),
    vaccinationStatus: z.string().trim().max(500).optional().nullable(),
    nextVisitDue: optionalDate,
  })
  .superRefine((data, ctx) => {
    const check = assertPlausibleMeasurements({
      weightKg: data.weightKg,
      heightCm: data.heightCm,
      headCircumferenceCm: data.headCircumferenceCm,
    });
    if (!check.ok) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: check.message,
        path: ["weightKg"],
      });
    }
  });

export type AddVisitInput = z.infer<typeof addVisitSchema>;

import { prisma } from "@/lib/db/prisma";

/**
 * Immutable human-readable patient IDs.
 * Format: `${PREFIX}${YYYYMMDDHHmm}-${seq}` e.g. ARJ202608121430-001
 * Sequence resets per minute bucket via PatientIdSequence (transactional).
 */
export function getPatientIdPrefix(): string {
  return (process.env.PATIENT_ID_PREFIX || "ARJ").toUpperCase();
}

export function formatMinuteBucket(date: Date = new Date()): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  const hh = String(date.getHours()).padStart(2, "0");
  const mm = String(date.getMinutes()).padStart(2, "0");
  return `${y}${m}${d}${hh}${mm}`;
}

export async function generatePatientId(
  at: Date = new Date(),
): Promise<string> {
  const prefix = getPatientIdPrefix();
  const bucketKey = formatMinuteBucket(at);

  const sequence = await prisma.$transaction(async (tx) => {
    const existing = await tx.patientIdSequence.findUnique({
      where: { id: "global" },
    });

    if (!existing) {
      await tx.patientIdSequence.create({
        data: { id: "global", bucketKey, sequence: 1 },
      });
      return 1;
    }

    if (existing.bucketKey === bucketKey) {
      const updated = await tx.patientIdSequence.update({
        where: { id: "global" },
        data: { sequence: { increment: 1 } },
      });
      return updated.sequence;
    }

    const reset = await tx.patientIdSequence.update({
      where: { id: "global" },
      data: { bucketKey, sequence: 1 },
    });
    return reset.sequence;
  });

  const seq = String(sequence).padStart(3, "0");
  return `${prefix}${bucketKey}-${seq}`;
}

